WITH RecentEmployees AS (SELECT *, DATE_SUB(hire_date, 30) hire_date_minus_30d FROM employees WHERE YEAR(hire_date) >= 2025 AND (level IN ('L2', 'L1') OR email IS NOT NULL)), summary AS (SELECT CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 46000 THEN 'mid' ELSE 'low' END salary_bucket, ROUND(AVG(salary), 2) avg_salary FROM RecentEmployees GROUP BY CASE WHEN salary >= 129000 THEN 'high' WHEN salary >= 46000 THEN 'mid' ELSE 'low' END) SELECT * FROM summary WHERE avg_salary >= 40 ORDER BY avg_salary DESC, salary_bucket LIMIT 1
